// src/pages/AdminDashboard/AdminDashboardPage.jsx
import { useState, useEffect } from "react";
import { useBooks } from "../../context/BooksContext";
import { useToast } from "../../context/ToastContext";
import { getDashboard, getUsers, deleteUser } from "../../services/adminService";
import { CATEGORIES } from "../../utils/mockData";
import Navbar from "../../components/Navbar/Navbar";
import "../../styles/components.css";
import styles from "./AdminDashboardPage.module.css";

const EMPTY_FORM = { title:"", author:"", category:"Drama", cover:"", readLink:"", description:"" };

function getBadgeClass(cat) {
  const map = { Fantasy:"badge-fantasy", Drama:"badge-drama", Detective:"badge-detective", Business:"badge-business" };
  return map[cat] || "badge-default";
}

export default function AdminDashboardPage() {
  const { books, addBook, deleteBook } = useBooks();
  const showToast = useToast();
  const [form, setForm]           = useState(EMPTY_FORM);
  const [formError, setFormError] = useState("");
  const [stats, setStats]         = useState(null);
  const [users, setUsers]         = useState([]);
  const [activeTab, setActiveTab] = useState("books");
  const [loadingStats, setLoadingStats] = useState(true);

  useEffect(() => {
    getDashboard()
      .then((res) => setStats(res.data.stats))
      .catch(() => {})
      .finally(() => setLoadingStats(false));
    getUsers()
      .then((res) => setUsers(res.data.data || res.data))
      .catch(() => {});
  }, []);

  setForm((p) => ({ ...p, [e.target.name]: e.target.value }));
  function handleChange(e) {
    setFormError("");
  }

  async function handleAdd(e) {
    e.preventDefault();
    if (!form.title.trim() || !form.author.trim()) { setFormError("Title and author are required"); return; }
    try {
      const payload = {
        ...form,
        // Keep backend compatibility across naming styles.
        read_link: form.readLink.trim(),
        link: form.readLink.trim(),
        Link: form.readLink.trim(),
      };
      await addBook(payload);
      setForm(EMPTY_FORM);
      showToast("The book has been added");
    } catch(err) {
      setFormError(err.response?.data?.message || "Book addition failed");
    }
  }

  async function handleDeleteBook(id) {
    if (!window.confirm("Are you sure you want to delete this book?")) return;
    try {
      await deleteBook(id);
      showToast("🗑️ The book has been deleted");
    } catch { showToast("❌ Failed to delete the book"); }
  }

  async function handleDeleteUser(id) {
    if (!window.confirm("Are you sure you want to delete this user?")) return;
    try {
      await deleteUser(id);
      setUsers((p) => p.filter((u) => u.id !== id));
      showToast("🗑️ The user has been deleted");
    } catch(err) {
      showToast(err.response?.data?.message || "❌ Failed to delete the user");
    }
  }

  const displayStats = stats || {
    total_books: books.length,
    total_users: users.length,
    total_categories: [...new Set(books.map((b) => b.category))].length,
  };

  return (
    <>
      <Navbar searchValue="" onSearchChange={() => {}} />
      <main className={styles.main}>
        <h1 className={styles.title}>Admin Dashboard</h1>
        <p className={styles.subtitle}>Manage library books and users</p>

        {/* Stats */}
        <div className={styles.stats}>
          <div className={styles.statCard}><div className={styles.statNum}>{displayStats.total_books}</div><div className={styles.statLabel}>Total Books</div></div>
          <div className={styles.statCard}><div className={styles.statNum}>{displayStats.total_users}</div><div className={styles.statLabel}>Total Users</div></div>
          <div className={styles.statCard}><div className={styles.statNum}>{displayStats.total_categories}</div><div className={styles.statLabel}>Categories</div></div>
        </div>

        {/* Tabs */}
        <div className={styles.tabs}>
          <button className={`${styles.tab} ${activeTab==="books"?styles.tabActive:""}`} onClick={()=>setActiveTab("books")}>📚 Management</button>
          <button className={`${styles.tab} ${activeTab==="addbook"?styles.tabActive:""}`} onClick={()=>setActiveTab("addbook")}>➕ Add Book</button>
          <button className={`${styles.tab} ${activeTab==="users"?styles.tabActive:""}`} onClick={()=>setActiveTab("users")}>👥 Management</button>
        </div>

        {/* Add Book */}
        {activeTab === "addbook" && (
          <section className={styles.section}>
            <h2 className={styles.sectionTitle}>➕ Add New Book</h2>
            {formError && <div className="alert alert-error">{formError}</div>}
            <form onSubmit={handleAdd}>
              <div className={styles.formGrid}>
                <div className="form-group"><label className="form-label">Book Title *</label><input className="form-input" name="title" placeholder="Book Title" value={form.title} onChange={handleChange} /></div>
                <div className="form-group"><label className="form-label">Author *</label><input className="form-input" name="author" placeholder="Author Name" value={form.author} onChange={handleChange} /></div>
                <div className="form-group"><label className="form-label">Category</label>
                  <select className="form-select" name="category" value={form.category} onChange={handleChange}>
                    {CATEGORIES.filter((c) => c !== "All").map((c) => <option key={c}>{c}</option>)}
                  </select>
                </div>
                <div className="form-group"><label className="form-label">Cover Image URL</label><input className="form-input" name="cover" placeholder="https://..." value={form.cover} onChange={handleChange} /></div>
                <div className="form-group"><label className="form-label">Read Link</label><input className="form-input" name="readLink" placeholder="https://..." value={form.readLink} onChange={handleChange} /></div>
              </div>
              <div className="form-group"><label className="form-label">Book Description</label><textarea className="form-textarea" name="description" placeholder="Brief description..." value={form.description} onChange={handleChange} /></div>
              <button type="submit" className="btn btn-primary">Add Book</button>
            </form>
          </section>
        )}

        {/* Books Table */}
        {activeTab === "books" && (
          <section className={styles.section}>
            <h2 className={styles.sectionTitle}>Management</h2>
            <div className={styles.tableWrap}>
              <table className={styles.table}>
                <thead><tr><th>Cover</th><th>Address</th><th>Category</th><th>Procedure</th></tr></thead>
                <tbody>
                  {books.map((book) => (
                    <tr key={book.id}>
                      <td><img src={book.cover} alt="" className={styles.miniCover} onError={(e)=>{e.target.src="https://via.placeholder.com/36x48/F5EFE3/9B8B7A?text=📖"}} /></td>
                      <td className={styles.bookTitle}>{book.title}</td>
                      <td>{book.author}</td>
                      <td><span className={`badge ${getBadgeClass(book.category)}`}>{book.category}</span></td>
                      <td><button className="btn btn-danger" onClick={() => handleDeleteBook(book.id)}>🗑️ Delete</button></td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </section>
        )}

        {/* Users Table */}
        {activeTab === "users" && (
          <section className={styles.section}>
            <h2 className={styles.sectionTitle}>👥 User Management ({users.length})</h2>
            <div className={styles.tableWrap}>
              <table className={styles.table}>
                <thead><tr><th>Image</th><th>Name</th><th>Username</th><th>Email</th><th>Role</th><th>Action</th></tr></thead>
                <tbody>
                  {users.map((u) => (
                    <tr key={u.id}>
                      <td>
                        {u.avatar
                          ? <img src={u.avatar} alt="" className={styles.userAvatar} />
                          : <div className={styles.userAvatarPlaceholder}>{u.name?.[0]?.toUpperCase()}</div>}
                      </td>
                      <td className={styles.bookTitle}>{u.name}</td>
                      <td>@{u.username}</td>
                      <td>{u.email}</td>
                      <td><span className={`badge ${u.role==="admin"?"badge-fantasy":"badge-default"}`}>{u.role}</span></td>
                      <td>
                        {u.role !== "admin" && (
                          <button className="btn btn-danger" onClick={() => handleDeleteUser(u.id)}>🗑️ Delete</button>
                        )}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </section>
        )}
      </main>
    </>
  );
}
